CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE CHECK(email=lower(email)),password_hash text NOT NULL,name text NOT NULL,role text NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','SELLER','CREATOR')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','BANNED')),email_verified boolean NOT NULL DEFAULT false,totp_secret text,totp_enabled boolean NOT NULL DEFAULT false,totp_last_counter bigint NOT NULL DEFAULT -1,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_creator ON users(role) WHERE role='CREATOR';
CREATE TABLE creator_identity(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),user_id uuid NOT NULL UNIQUE REFERENCES users(id));
CREATE FUNCTION protect_creator() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.role='CREATOR' AND (TG_OP='DELETE' OR NEW.role<>'CREATOR' OR NEW.status<>'ACTIVE') THEN RAISE EXCEPTION 'Creator cannot be removed or downgraded'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER creator_protection BEFORE UPDATE OR DELETE ON users FOR EACH ROW EXECUTE FUNCTION protect_creator();
CREATE TABLE sessions(id_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),stage text NOT NULL CHECK(stage IN('FULL','TOTP','TOTP_SETUP')),device_hash text,ip text,user_agent text,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recovery_codes(user_id uuid REFERENCES users(id),code_hash text NOT NULL UNIQUE,used_at timestamptz);
CREATE TABLE trusted_devices(user_id uuid REFERENCES users(id),device_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,device_hash));
CREATE TABLE login_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),ip text,result text NOT NULL,device_hash text,user_agent text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE seller_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),bio text DEFAULT '',avatar_asset_id uuid,links jsonb NOT NULL DEFAULT '{}',verified boolean NOT NULL DEFAULT false,identity_approved boolean NOT NULL DEFAULT false,tax_id_cipher text,tax_id_hash text,frozen boolean NOT NULL DEFAULT false,freeze_reason text,commission_override numeric(5,2) CHECK(commission_override BETWEEN 0 AND 100),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,parent_id uuid REFERENCES categories(id),active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,UNIQUE(name,parent_id));
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),short text NOT NULL DEFAULT '' CHECK(length(short)<=160),description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',subcategory text NOT NULL DEFAULT '',development_status text NOT NULL DEFAULT 'Terminado' CHECK(development_status IN('Terminado','En desarrollo','Prototipo','Abandonado')),publication_status text NOT NULL DEFAULT 'DRAFT' CHECK(publication_status IN('DRAFT','REVIEW','PUBLISHED','HIDDEN','DELETING','DELETED')),reference text NOT NULL DEFAULT '',tool text NOT NULL DEFAULT '',formats text[] NOT NULL DEFAULT '{}',version text NOT NULL DEFAULT '1.0',changelog text NOT NULL DEFAULT '',requirements text NOT NULL DEFAULT '',compatibility text NOT NULL DEFAULT '',license text NOT NULL DEFAULT 'Uso personal',custom_license text NOT NULL DEFAULT '',tags text[] NOT NULL DEFAULT '{}',price bigint NOT NULL DEFAULT 0 CHECK(price>=0),currency text NOT NULL DEFAULT 'USD' CHECK(currency IN('USD','ARS')),demo text NOT NULL DEFAULT '',repository text NOT NULL DEFAULT '',installation text NOT NULL DEFAULT '',video_url text NOT NULL DEFAULT '',featured boolean NOT NULL DEFAULT false,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX project_search ON projects USING gin(to_tsvector('spanish',title||' '||short||' '||description));
CREATE INDEX project_catalog ON projects(publication_status,category,price);
CREATE TABLE project_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),version text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),project_id uuid REFERENCES projects(id),version_id uuid REFERENCES project_versions(id),purpose text NOT NULL CHECK(purpose IN('main','image','video','identity_front','identity_back','selfie','receipt')),object_key text NOT NULL UNIQUE,bucket text NOT NULL,original_name text NOT NULL,size bigint NOT NULL CHECK(size>0),mime text,real_type text,checksum text,status text NOT NULL DEFAULT 'UPLOADING' CHECK(status IN('UPLOADING','QUARANTINE','SCANNING','CLEAN','REJECTED','DELETING','DELETED')),multipart_id text,upload_fingerprint text,scan_reason text,sort_order integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX resumable_upload_identity ON assets(owner_id,coalesce(project_id,'00000000-0000-0000-0000-000000000000'::uuid),purpose,upload_fingerprint) WHERE upload_fingerprint IS NOT NULL AND status NOT IN('REJECTED','DELETED');
CREATE TABLE identity_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),full_name_cipher text NOT NULL,tax_id_cipher text NOT NULL,tax_id_hash text NOT NULL,front_id uuid REFERENCES assets(id),back_id uuid REFERENCES assets(id),selfie_id uuid REFERENCES assets(id),status text NOT NULL DEFAULT 'PENDING',reason text,reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bank_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid REFERENCES users(id),currency text NOT NULL CHECK(currency IN('USD','ARS')),details_cipher text NOT NULL,account_hash text NOT NULL,tax_id_hash text NOT NULL,verified boolean NOT NULL DEFAULT false,next_withdrawal_review boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,kind text NOT NULL CHECK(kind IN('PERCENT','FIXED')),value bigint NOT NULL CHECK(value>0),currency text CHECK(currency IN('USD','ARS')),scope text NOT NULL DEFAULT 'GLOBAL' CHECK(scope IN('GLOBAL','PROJECT','CATEGORY')),project_id uuid REFERENCES projects(id),category text,expires_at timestamptz NOT NULL,max_uses integer NOT NULL CHECK(max_uses>0),active boolean NOT NULL DEFAULT true);
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES users(id),project_id uuid NOT NULL REFERENCES projects(id),seller_id uuid NOT NULL REFERENCES users(id),currency text NOT NULL CHECK(currency IN('USD','ARS')),original_price bigint NOT NULL CHECK(original_price>=0),discount bigint NOT NULL CHECK(discount>=0),gross bigint NOT NULL CHECK(gross>=0),commission bigint NOT NULL CHECK(commission>=0),net bigint NOT NULL CHECK(net>=0),rate numeric(5,2) NOT NULL,license_snapshot text NOT NULL,title_snapshot text NOT NULL,deletion_accepted_at timestamptz NOT NULL,legal_version text NOT NULL,coupon_id uuid REFERENCES coupons(id),status text NOT NULL DEFAULT 'CREATED' CHECK(status IN('CREATED','PAID','CANCELLED','REFUNDED','PARTIALLY_REFUNDED','DISPUTED','REVERSED')),provider_order_id text UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',created_at timestamptz NOT NULL DEFAULT now(),CHECK(gross=commission+net),CHECK(original_price=discount+gross));
CREATE UNIQUE INDEX one_active_order ON orders(buyer_id,project_id) WHERE status IN('CREATED','PAID','DISPUTED','PARTIALLY_REFUNDED');
CREATE TABLE captures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),provider text NOT NULL,provider_id text NOT NULL UNIQUE,gross bigint NOT NULL,fee bigint NOT NULL DEFAULT 0,received bigint NOT NULL,currency text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events(id text PRIMARY KEY,provider text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,verified boolean NOT NULL DEFAULT false,processed_at timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),project_id uuid NOT NULL REFERENCES projects(id),order_id uuid REFERENCES orders(id),origin text NOT NULL CHECK(origin IN('FREE','PURCHASE')),revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,project_id));
CREATE TABLE download_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),project_id uuid REFERENCES projects(id),asset_id uuid REFERENCES assets(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_key text NOT NULL,currency text NOT NULL CHECK(currency IN('USD','ARS')),kind text NOT NULL,UNIQUE(owner_key,currency,kind));
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_key text NOT NULL UNIQUE,kind text NOT NULL,reference_id text NOT NULL,currency text NOT NULL CHECK(currency IN('USD','ARS')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_entries(id bigserial PRIMARY KEY,transaction_id uuid NOT NULL REFERENCES ledger_transactions(id),account_id uuid NOT NULL REFERENCES ledger_accounts(id),amount bigint NOT NULL CHECK(amount<>0));
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER ledger_transactions_immutable BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER ledger_entries_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE FUNCTION check_journal() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE t uuid; total bigint; mismatch bigint; BEGIN t=NEW.transaction_id; SELECT coalesce(sum(e.amount),0), count(*) FILTER(WHERE a.currency<>j.currency) INTO total,mismatch FROM ledger_entries e JOIN ledger_accounts a ON a.id=e.account_id JOIN ledger_transactions j ON j.id=e.transaction_id WHERE e.transaction_id=t; IF total<>0 OR mismatch<>0 THEN RAISE EXCEPTION 'Unbalanced or mixed-currency journal'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal();
CREATE TABLE wallets(seller_id uuid REFERENCES users(id),currency text NOT NULL CHECK(currency IN('USD','ARS')),pending bigint NOT NULL DEFAULT 0 CHECK(pending>=0),available bigint NOT NULL DEFAULT 0 CHECK(available>=0),reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0),withdrawn bigint NOT NULL DEFAULT 0 CHECK(withdrawn>=0),debt bigint NOT NULL DEFAULT 0 CHECK(debt>=0),PRIMARY KEY(seller_id,currency));
CREATE TABLE sale_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),seller_id uuid NOT NULL REFERENCES users(id),currency text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),release_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','RELEASED','BLOCKED','REVERSED')));
CREATE TABLE withdrawals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),amount bigint NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency IN('USD','ARS')),bank_id uuid REFERENCES bank_accounts(id),bank_snapshot text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PROCESSING','PAID','REJECTED')),manual_review boolean NOT NULL DEFAULT true,idempotency_key uuid NOT NULL UNIQUE,reason text,operation_number text,receipt_id uuid REFERENCES assets(id),taken_by uuid REFERENCES users(id),due_at timestamptz NOT NULL,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE withdrawal_events(id bigserial PRIMARY KEY,withdrawal_id uuid REFERENCES withdrawals(id),actor_id uuid REFERENCES users(id),action text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id),provider_id text UNIQUE,amount bigint NOT NULL CHECK(amount>0),net_amount bigint NOT NULL DEFAULT 0,commission_amount bigint NOT NULL DEFAULT 0,reason text NOT NULL,status text NOT NULL DEFAULT 'REQUESTED',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE disputes(id text PRIMARY KEY,order_id uuid REFERENCES orders(id),status text NOT NULL,amount bigint,reason text,raw jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid REFERENCES projects(id),author_id uuid REFERENCES users(id),parent_id uuid REFERENCES comments(id),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000),highlighted boolean NOT NULL DEFAULT false,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION check_reply() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM comments WHERE id=NEW.parent_id AND parent_id IS NULL AND project_id=NEW.project_id) THEN RAISE EXCEPTION 'Only one reply level on same project'; END IF; RETURN NEW; END $$;
CREATE TRIGGER comment_depth BEFORE INSERT OR UPDATE ON comments FOR EACH ROW EXECUTE FUNCTION check_reply();
CREATE TABLE ratings(user_id uuid REFERENCES users(id),project_id uuid REFERENCES projects(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,project_id));
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid REFERENCES users(id),project_id uuid REFERENCES projects(id),comment_id uuid REFERENCES comments(id),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE copyright_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,project_url text NOT NULL,original_url text NOT NULL,description text NOT NULL,declaration boolean NOT NULL CHECK(declaration),status text NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blocklist(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('EMAIL','IP','BANK')),value_hash text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,value_hash));
CREATE TABLE collections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true);
CREATE TABLE collection_projects(collection_id uuid REFERENCES collections(id),project_id uuid REFERENCES projects(id),position integer NOT NULL DEFAULT 0,PRIMARY KEY(collection_id,project_id));
CREATE TABLE banners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,link text NOT NULL,image_id uuid REFERENCES assets(id),active boolean NOT NULL DEFAULT true);
CREATE TABLE announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,audience text NOT NULL DEFAULT 'ALL',expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_templates(key text PRIMARY KEY,subject text NOT NULL,body text NOT NULL);
CREATE TABLE campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject text NOT NULL,body text NOT NULL,audience text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE communication_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),marketing boolean NOT NULL DEFAULT false,unsubscribe_token text NOT NULL UNIQUE DEFAULT replace(gen_random_uuid()::text||gen_random_uuid()::text,'-',''));
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_key text UNIQUE NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE search_events(id bigserial PRIMARY KEY,query text NOT NULL,results integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,version text NOT NULL,body text NOT NULL,active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,version));
CREATE TABLE legal_acceptances(user_id uuid REFERENCES users(id),version text NOT NULL,kind text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,version,kind));
CREATE TABLE privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),kind text NOT NULL,status text NOT NULL DEFAULT 'PENDING',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,target_id text,ip text,metadata jsonb NOT NULL DEFAULT '{}',previous_hash text NOT NULL,event_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE reconciliation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),status text NOT NULL DEFAULT 'PENDING',summary jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid REFERENCES reconciliation_runs(id),external_id text,currency text,expected bigint,actual bigint,difference bigint);
CREATE TABLE backup_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_key text,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deletion_tombstones(project_id uuid PRIMARY KEY,requested_at timestamptz NOT NULL DEFAULT now(),purged_at timestamptz);
